// §14.3 Paquetes: recepcion, los dos recordatorios y el escalamiento.
//
// Los plazos (24 h, 72 h, 7 dias) NO estan aqui. Los decide el @Scheduled de
// Spring con el Clock inyectado, y cada aviso tiene su bandera en base para no
// repetirse (§6, §9). n8n se limita a redactar lo que ya ocurrio: si hace falta
// cambiar un plazo, se cambia en porteria.paquetes.* y no en este nodo.

const esperado = $env.PORTERIA_SECRET;
const admin = $env.CORREO_ADMINISTRACION || 'administracion@example.test';
const salida = [];

for (const item of $input.all()) {
  const cabeceras = item.json.headers || {};
  const evento = item.json.body || item.json;

  if (esperado) {
    const recibido = cabeceras['x-porteria-secret'] || cabeceras['X-Porteria-Secret'];
    if (recibido !== esperado) {
      throw new Error('X-Porteria-Secret invalido: evento descartado');
    }
  }

  const d = evento.datos || {};
  const apto = d.apartamento || 'sin apartamento';
  let destinatario = d.correoResidente || admin;
  let asunto;
  let texto;

  switch (evento.tipo) {
    case 'PAQUETE_RECIBIDO':
      asunto = 'Tienes un paquete en porteria';
      texto = [
        'Llego un paquete para el apartamento ' + apto + ': ' + d.descripcion + '.',
        d.remitente ? 'Remitente: ' + d.remitente : '',
        '',
        'CODIGO DE RETIRO: ' + d.codigoRetiro,
        '',
        'Presenta este codigo en porteria, o pide que lo retire alguien que',
        'tengas registrado como autorizado a retirar.',
      ].filter(Boolean).join('\n');
      break;

    case 'PAQUETE_RECORDATORIO':
      asunto = 'Recordatorio: paquete sin retirar (' + d.hitoHoras + ' h)';
      texto = [
        'El paquete "' + d.descripcion + '" sigue en porteria.',
        'Lleva ' + d.horasSinRetirar + ' horas sin retirar.',
        'Recibido el ' + d.recibidoEn + '.',
        '',
        'A los 7 dias se escala a la administracion.',
      ].join('\n');
      break;

    case 'PAQUETE_ESCALADO':
      // Este no va al residente: va a administracion, que es a quien se escala.
      destinatario = admin;
      asunto = 'Paquete escalado: apartamento ' + apto;
      texto = [
        'El paquete "' + d.descripcion + '" del apartamento ' + apto + ' lleva',
        d.diasSinRetirar + ' dias sin retirar y se escala a administracion.',
        '',
        'Recibido el ' + d.recibidoEn + '.',
      ].join('\n');
      break;

    default:
      console.log('Tipo que no corresponde a este flujo: ' + evento.tipo);
      continue;
  }

  salida.push({ json: { tipo: evento.tipo, destinatario, asunto, texto } });
}

return salida;
